INSERT INTO `department_translations` (`id`, `department_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('16', '4', 'ar', 'تخزين المنتجات الزراعية وتكنولوجيا الزيوت والدهون', 'تخزين المنتجات الزراعية وتكنولوجيا الزيوت والدهون', 'On the basis of the newly created structure of the institute, the department started its work in August 2022 under the name of the department \"Storage, processing and oil technology of agricultural products\", separated from the department \"Food technology\". The department trains specialists in the following areas:', '[{\"key\":\"overview\",\"title\":\"\\u0646\\u0638\\u0631\\u0629 \\u0639\\u0627\\u0645\\u0629\",\"items\":[\"Department of Storage, Processing, and Oil-Fat Technology of Agricultural Products     \\n\\nMajidova Nargiza Kaxramonovna\\n Reception time: Dushanba-Juma (14:00-16:00 gacha)\\n Phone: +998 97 305 95 59\\n Email: nargiz-1234n@mail.ru\"]},{\"key\":\"history\",\"title\":\"\\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0644\\u0642\\u0633\\u0645\",\"items\":[\"On the basis of the newly created structure of the institute, the department started its work in August 2022 under the name of the department \\\"Storage, processing and oil technology of agricultural products\\\", separated from the department \\\"Food technology\\\". The department trains specialists in the following areas:\",\"There are 12 professors and teachers at the department, including 2 doctors of science, 2 candidates of science, associate professor, 4 doctors of science (PhD), 2 assistants, 1 trainee whose scientific potential is 78%.\"]},{\"key\":\"staff\",\"title\":\"\\u0623\\u0639\\u0636\\u0627\\u0621 \\u0647\\u064a\\u0626\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633 \\u0641\\u064a \\u0627\\u0644\\u0642\\u0633\\u0645\",\"items\":[\"Head of the department, Doctor of Technical Sciences, associate professor\\nMajidova Nargiza Kakhramonovna\",\"Doctor of Technical Sciences, professor\\nMajidov Qakhramon Khalimovich\",\"Candidate of the technical science, associate professor\\nAshurov Furkat Bakhromovich\",\"PhD, dotsent\\nSabirova Nargiza Nusratovna\",\"PhD, associate professor\\nBozorov Dilmurod Kholmurodovich\",\"PhD, dotsent\\nOltiev Azim To`yqulovich\",\"assistent\\nFayzullaev Asqar Rajabboevich\",\"PhD, Senior Lecturer\\nMirzaeva Shokhista Usmonovna\",\"PhD, dotsent\\nRadjabova Lobar Ramazonovna\",\"assistent\\nFatayeva Farodiba Rustamovna\",\"Teacher, trainee\\nShodiev Bakhtiyor\"]},{\"key\":\"prepared_specialists\",\"title\":\"\\u0627\\u0644\\u062a\\u062e\\u0635\\u0635\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u064a\\u062a\\u0645 \\u0625\\u0639\\u062f\\u0627\\u062f\\u0647\\u0627\",\"items\":[\"Bachelor\'s degree\\n60811300 - Technology of\\nstorage and processing of agricultural products 60811800 - Fruit and viticulture\\n60720100 - Food technology (oil and oil products)\\n60720200 - Technology of fats, essential oils and perfumes cosmetics\\n70720101 - Technology of production and processing of food products (oil and oil products)\\nJudiciary\\n70720701 - Technology of storage and processing of agricultural products, master\\ndegree 02.00.17. - Direction code of the doctrine \\\"Technologies and biotechnologies for processing, storage and processing of agricultural and food products\\\"\"]},{\"key\":\"subjects\",\"title\":\"\\u0627\\u0644\\u0645\\u0642\\u0631\\u0631\\u0627\\u062a \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u064a\\u0629\",\"items\":[\"Bachelor\'s Degree:\",\"60811300-Q Technology of storage and processing of agricultural products, for bachelor\'s degree\",\"1.Biology and genetics\\n2.Biophysics and agrometeorology\\n3.Botany and plant physiology\\n4. Commodity organization of agricultural products\\n5.Fruit and vegetable growing\\n6.Plant growing\\n7.Fundamentals of safety of agricultural products\\n8.Physicochemical methods for determining the quality of agricultural products\\n9.Technology of storage and processing of fruits and vegetables\\n10. Technology of storage and processing of dairy and meat products\",\"60811800 - Bachelor\'s degree in fruit and viticulture\",\"1.Biology of fruit crops\\n2.Soil science and agrochemistry\\n3.Farming and melioration\\n4.Technology of grape cultivation\\n5.Vegetable growing and melon\\ngrowing 6.Intensive fruit growing\\n7.Selection and ampelography of grapes\",\"60720100 - Food Technology (Fatty and Fat Products) Bachelor\",\"1.Chemistry of oils and oily raw materials\\n2.Technology of production of vegetable oils\\n3.Technology of oil processing 4.Technology\\nof storage and packaging of oil-and-oil products 5.Methods\\nand expertise of research of oils and oils\\n6.Surfactants in the production of oil-and-oil products\",\"60720200 - Technology of Oils, Essential Oils and Perfumery, Cosmetics, Bachelor\'s degree\",\"1.Technology of production of essential oils\\n2.Raw materials of perfumery and cosmetic products\\n3.Fragrances and dyes\\n4.Technology of production of perfume and cosmetic products 5.Storage\\nand packaging of perfume and cosmetic products\\n6.Fragrances and dyes\",\"Judiciary\",\"70720101 \\u2013 Technology of production and processing of food products (oil-and-oil products) with a degree in master\'s degree\",\"1.Chemistry of oils and oils\\n2.Refining and catalytic modification of oils\\n3.Technology of production of solid oils and detergents\\n4.Fundamentals of\\ncatalysis and potassium 5.Product expertise of oils and oils\\n6.Fundamentals of lubrication of oil-and-oil enterprises\",\"Republication of publications\\nSUBJECTS (TEXTBOOKS) (textbooks, electronic textbooks and teaching aids)\\n1. Q.Kh.Majidov, F.B.Ashurov, K.K.Sattorov, F.F.Ashurov textbook on the subject \\\"Fundamentals of food technology\\\"\\n2. K.Kh.Majidov, R.A.Makhmudov, N.K.Majidova textbook on \\\"Food chemistry and biochemistry\\\"\\n3. K.Kh.Majidov, S.SH. Ismatov, N.K.Majidova \\\"Technology of oil processing\\\" Textbook\\n4.N.K.Mazhidova, N.N.Sabirova \\\"Food chemistry and biochemistry\\\"\\n5.K.Kh.Majidov, N.K.Majidova \\\"Technology of production of vegetable oils\\\"\\nElectronic textbook 6. Q.S.Rakhmonov Textbook on the topic \\\"Educational research work of students\\\".2024\\n7. U.K.Khujakulova, N.K.Majidova, A.R.Fayzullaev, Q.S.Rakhmonov, N.F.Khujakulova textbooks on the topic \\\"Technology of production of vegetable oils\\\". 2024\\n8. Q.S.Rakhmonov, L.N.Khaidar-Zade, U.K.Khujakulov, Sh.M.Kurbanova textbooks for laboratory classes on the topic \\\"Technology of production of confectionery products\\\". 2024\\n9. N.N.Sabirova, Q.Kh.Majidov, N.K.Majidova textbooks on the topic \\\"Technology of production of perfume and cosmetic products\\\". 2024\\n10. Q.Kh.Majidov, U.K.K.Khujakulov, N.K.Majidova, N.N.Sabirova textbooks on the topic \\\"Raw materials of perfumery, cosmetic products\\\". 2024\\n11. A.R.Fayzullaev textbook on the subject \\\"Technology of storage and packaging of oil and oil products\\\". 2024\\n12. F.N.Ashurov, B.M.Shodiev electronic textbook on the subject \\\"Technology of storage and packaging of oil and oil products\\\". 2024\\n13. B.M.Shodiev, F.N.Ashurova electronic textbook for the division of fruit plants into biological economic groups from the topic \\\"Technology of cultivation of fruit crops\\\". 2024\\n14. Q.Kh.Majidov, N.K.Majidova, N.N.Sabirova Electronic textbook on the subject \\\"Technology of production of essential oils\\\".2024\\n15. Electronic textbook on practical training of M.A.Tursunova, N.K.Majidova in the subject \\\"Biology\\\". 2024\\n16. L.N.Khaidar-Zade, Q.S.Rakhmonov, U.M.Ibragimov electronic textbook for practical lessons on the subject \\\"Fundamentals of food security\\\" (in Russian). 2024\\n17. N.R.Dzhuraeva, T.I.Atamuratova, Q.S.Rakhmonov, S.K.Jabbarova electronic textbook for lecture classes on the subject \\\"Equipment and basics of design of enterprises for the production of bread, pasta and confectionery\\\". 2024\\n18. L.N.Haidar-Zade, Q.S.Rakhmonov, Sh.Zh.Yuldashev, A.S.Elmurodova, U.M.Ibragimov on the subject \\\"Fundamentals of food security\\\" Electronic textbook for. 2024\\n19. Q.S.Rakhmonov, D.I.Umarov, N.Kh.Hakimova, O\'. M.Yakyieva, electronic textbook for lectures on the subject \\\"Technology of storage and processing of grain and grain products\\\". 2024\\n20. M.M.Sadikova, N.N.Sabirova, D.J.Khujakulova \\\"General chemical technology\\\". 2024\"]},{\"key\":\"research\",\"title\":\"\\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0628\\u062d\\u062b\\u064a\\u0629\",\"items\":[\"SCIENTIFIC ARTICLES IN JOURNALS PUBLISHED ON INTERNATIONALLY RECOGNIZED DATABASES \\u00abWEB OF SCIENCE\\u00bb, \\u00abSCOPUS\\u00bb AND OTHERS\\n1.Majidov Kakhramon Halimovich. Majidova Nargiza Kakhramonovna The evalution of catalysts for the hydrogenation of oil sand fats. International Journal of Early Childhood Special Education. Vol 14, Issue 05 2022 pp 3994-3997\\n2.Majidova Nargiza Kakhramonovna. Excellense in detergent production technology. International Journal of Advanced Research in IT and Engineering Vol. 11 No. 5 May 2022 \\u0420-23-27\\n3.Majidova Nargiza Kakhramonovna \\u041eptimization of Technological Parameters For Deodorization of Vegetable Oils. . International Journal of Innovative Research in Science, Engineering and Technology Volume 10, Issue 12, December 2021.\\u0420-15388-15389\\n4.Majidova Nargiza Kakhramonovna. Application of mathematical processing methods for optimizing the hydrogenating catalysts. Accepted in the journal The American Journal of Engineering and Technology. Volume 03 Issue 05 May 2021. \\u0420-23-27\\n5. Majidov Kakhramon Halimovich. Theoretical approach to the evaluation of catalysts for the hydrogenation of oils and fats International Journal of Mechanical Engineering. Vol. 7 No. 1 January, 2022\\n6. Majidov Kakhramon Halimovich.The development of an optimal formulation of detergent. International Journal of advanced research in Science, Engineering and Technology Volume 8, Issue 1, January 2021.\\u0420-16516-16518\\n7. \\u0421\\u0430\\u0431\\u0438\\u0440\\u043e\\u0432\\u0430 \\u041d\\u0430\\u0440\\u0433\\u0438\\u0437\\u0430 \\u041d\\u0443\\u0441\\u0440\\u0430\\u0442\\u043e\\u0432\\u043d\\u0430. \\u041f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0448\\u043e\\u0440\\u0442\\u0435\\u043d\\u0438\\u043d\\u0433 \\u0436\\u0438\\u0440\\u043e\\u0432 \\u0432 \\u043c\\u0430\\u0440\\u0433\\u0430\\u0440\\u0438\\u043d\\u043e\\u0432\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u0438. \\u00abUniversum: \\u0422\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043d\\u0430\\u0443\\u043a\\u0438\\u00bb \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b. \\u0420\\u043e\\u0441\\u0441\\u0438\\u044f 2020. \\u211611 (80)\\n8. \\u0421\\u0430\\u0431\\u0438\\u0440\\u043e\\u0432\\u0430 \\u041d\\u0430\\u0440\\u0433\\u0438\\u0437\\u0430 \\u041d\\u0443\\u0441\\u0440\\u0430\\u0442\\u043e\\u0432\\u043d\\u0430. \\u0418\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0442\\u0435\\u043c\\u043f\\u0435\\u0440\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0445 \\u0441\\u0432\\u043e\\u0439\\u0441\\u0442\\u0432 \\u0448\\u043e\\u0440\\u0442\\u0435\\u043d\\u0438\\u043d\\u0433-\\u0436\\u0438\\u0440\\u043e\\u0432 \\u043d\\u0430 \\u043e\\u0441\\u043d\\u043e\\u0432\\u0435 \\u0445\\u043b\\u043e\\u043f\\u043a\\u043e\\u0432\\u043e\\u0433\\u043e \\u043c\\u0430\\u0441\\u043b\\u0430\\/\\/UNIVERSUM: \\u0422\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043d\\u0430\\u0443\\u043a\\u0438. \\u041d\\u0430\\u0443\\u0447\\u043d\\u044b\\u0439 \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b. \\u2116 9 (66), \\u0421.81-85, \\u041c\\u043e\\u0441\\u043a\\u0432\\u0430, 2019.\\n9. Sabirova Nargiza Nusratovna. Characteristics of new kinds of shortenings\\/\\/ Austrian Journal of Technical and Natural Sciences \\u2116 11-12, Vienna 2018 November December, pp.16-19 9. 10.Sabirova Nargiza Nusratovna. Indicators providing quality and safety of food products Biomedical Journal of Scientific & Technical Research. The USA-2018. Vol.5, Issue 5.\\n10.Oltiev Azim To`yqulovich. Improvement of the technology of catalytic hydrogenization of cotton oil. Journal of nutrition and food processing, Auctores Publishing \\u2013 Volume1-10009\\nLEADING SCIENTIFIC WORK AT THE DEPARTMENT:\\nAltiev Azim Toykulovich \\u2013 Improvement of the technology of pereetirization of oil and oil mixture with use of efficient catalysts.\\nFayzullaev Askar Rajabboevich - Fundamentals of improvement of the technology for obtaining powdery products from processing of raw materials with roots.\"]},{\"key\":\"cooperation\",\"title\":\"\\u0627\\u0644\\u062a\\u0639\\u0627\\u0648\\u0646\",\"items\":[\"In the sphere of international cooperation the department works with the following educational institutions:\\n1. Al-Farabi Kazakh National University,\\n2. Karaganda technical university named after A.Saginov,\\n3. South Kazakhstan University named after M.Auesov,\\n4. University of Copenhagen, Denmark,\\n5. University of Extramadura in Spain.\",\"NEWS\\n1. Selection and formation of candidates for sending professors and teachers to targeted doctoral studies or internships in higher educational institutions and research centers included in the foreign TOP-500.\\n2. Bringing the scientific potential of the department to 80%, the share of professors and teachers with national or international certificates on foreign languages by 30%.\\n3. Organization of 1 SPIN-OFF enterprise, corresponding to the direction of education, and the organization of students\' practices in the enterprises or workshops of this LLC.\\n4. Development of research works based on the experience of developed foreign countries and an increase in the size of international grants within the framework of joint research projects with them.\\n5. Implementation of foreign investments by implementing existing projects in the department with foreign partners.\"]}]', 'تخزين المنتجات الزراعية وتكنولوجيا الزيوت والدهون', 'On the basis of the newly created structure of the institute, the department started its work in August 2022 under the name of the department \"Storage, processing and oil technology of agricultural products\", separated from the department \"Food techn', '2026-07-26 00:16:43', '2026-07-27 06:31:47');
INSERT INTO `department_translations` (`id`, `department_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('17', '5', 'en', 'Oil and Gas Engineering (Upstream & Downstream)', 'Oil and Gas Engineering (Upstream & Downstream)', 'The Department of Oil and Gas Business was organized on the basis of the Department of \"Technology of Oil and Gas Chemical Industry\" in accordance with the new structure of the Bukhara Engineering and Technological Institute, approved by the Ministry of Higher and Secondary Special Education of the Republic of Uzbekistan on July 10, 2019. The management of the department is entrusted to the candidate of chemical sciences, associate professor Q.Q.Sharipov.\nAt the department 1 doctor of sciences - professor, 1 candidate of sciences - associate professor, 4 doctors of philosophy (PhD), 2 senior teachers, 2 assistant teachers teach students.\nIn the 2021-2022 academic year, the Department of Oil and Gas Affairs organized the educational process for the following undergraduate and master\'s specialties:', '[{\"key\":\"overview\",\"title\":\"Overview\",\"items\":[\"Department of Oil and Gas Engineering           \\n\\nSharipov Qaxramon Qandiyorovich\\n Reception time: Every day 15:00-16: 00\\n Phone: +998 93 453 69 69\\n Email: kahramon.sharipov@mail.ru\"]},{\"key\":\"history\",\"title\":\"Department History\",\"items\":[\"The Department of Oil and Gas Business was organized on the basis of the Department of \\\"Technology of Oil and Gas Chemical Industry\\\" in accordance with the new structure of the Bukhara Engineering and Technological Institute, approved by the Ministry of Higher and Secondary Special Education of the Republic of Uzbekistan on July 10, 2019. The management of the department is entrusted to the candidate of chemical sciences, associate professor Q.Q.Sharipov.\\nAt the department 1 doctor of sciences - professor, 1 candidate of sciences - associate professor, 4 doctors of philosophy (PhD), 2 senior teachers, 2 assistant teachers teach students.\\nIn the 2021-2022 academic year, the Department of Oil and Gas Affairs organized the educational process for the following undergraduate and master\'s specialties:\"]},{\"key\":\"prepared_specialists\",\"title\":\"Prepared Specialists\",\"items\":[\"UNDERGRADUATE DEGREE\\n60721800-Oil and gas works (start-up and development of oil and gas fields)\\n5311900-Oil and gas works (start-up and development of oil and gas fields)\\n5311900 - Start-up and exploitation of oil and gas fields\\nJUDICIARY\\n70721802- The use of machinery and equipment for oil and gas fields\\n5A311902 - The use of machinery and equipment of oil and gas fields\"]},{\"key\":\"subjects\",\"title\":\"Taught Subjects\",\"items\":[\"Bachelor\'s Degree:\\n1.Geology of oil and gas\\n2.Fundamentals\\nof geophysics 3.General and underground hydraulics\\n4.Fundamentals of oil and gas work\\n5.Machinery and equipment of oil and gas fields\\n6.Mechanics of rocks\\n7.Protection against corrosion\\n8.Collection, preparation and transfer of oil and gas\\n9.Geology of oil and gas fields\\n10.Geophysical control\\nof the operation of oil and gas fields 11.Drilling of oil and gas wells\\n12.Equipment of oil and gas fields\\n13.Capital and underground repair\\nof wells 14.Technology of increasing oil and gas supply of reservoirs\\n15.Use of pumping and compressor stations\\nJudiciary\\n1. Machinery and equipment of oil and gas fields\\n2. Machinery and equipment for the repair of oil and gas\\nwells 3. Theoretical foundations\\nof the exploitation of oil and gas fields 4. Installation and operation of equipment for oil and gas\\nwells 5. Equipment of oil and gas gathering and preparation facilities in the fields\"]},{\"key\":\"staff\",\"title\":\"Professor-Teachers of the Department\",\"items\":[\"Sharipov Qakhramon Kandiyorovich - Head of the department, Ph.D., associate Professor\\nDustov Khamro Bozorovich - Professor, Ph.D.\\nToshev Sherzod Orzievich - Associate Professor, PhD Bozorov Jurabek Toronovich - Associate Professor, PhD\",\"Ochilov Abdurahim Abdurasulovich - Associate Professor, PhD\\nRakhimov Bobomurod Rustamovich - Assistant, PhD\\nObidov Hamid Olimovich - Senior Lecturer Sattorov\\nMirvohid Olimovich - Senior Lecturer\\nYamaletdinova Aygul Akhmadovna - assistant\\nBokieva Shakhnoza Komilovna - assistant\"]},{\"key\":\"publications\",\"title\":\"Textbooks and Articles\",\"items\":[\"1. O\\u2019quv-uslubiy majmualar \\u2013 50 dan ortiq;\\nUslubiy qo\\u2019llanmalar \\u2013 16 ta;\\nMa\\u2019ruza matnlari - 50 dan ortiq;\\nUslubiy ko\\u2019rsatmalar \\u2013 60 dan ortiq.\",\"ILMIY MAQOLALAR\\nXorijiy maqolalar \\u2013 150 dan ortiq\\nRespublika maqolalari \\u2013 200 dan ortiq\",\"ANJUMANLARDAGI TEZIS VA MAQOLALAR (XALQARO VA RESPUBLIKA)\\nXalqaro tezislar \\u2013 300 dan ortiq;\\nRespublika tezislari \\u2013 250 dan ortiq;\",\"SCOPUS VA WEB OF SCIENCE BAZASIGA KIRGAN ILMIY ISHLAR\",\"Toshev Sherzod Orzievich, Obidov Xamid Olimovich. AGRITECH-V-2021. Features of the chemical composition andcolloidal-chemical properties of local clays of Uzbekistan and their comparison with other clays 2021, \\u211612, p.31-34\\nOchilov Abduraxim Abdurasulovich, Sattorov Mirvohid Olimovich, Yamaletdinova Aygul Axmadovna, Bokieva Shahnoza Komilovna. Earth and Environmental Science. Reduction the viscosity of oil-slime emulsions of heavy oils using gas condensate. 839 (2021) 042082. doi:10.1088\\/1755-1315\\/839\\/4\\/042082\\nSattorov Mirvohid Olimovich, Ochilov Abduraxim Abdurasulovich, Yamaletdinova Aygul Axmadovna, Bokieva Shahnoza Komilovna. Earth and Environmental Science. Breakdown of local oil-water emulsions by binary systems of surface-active substances. 839 (2021) 042085. IOP Publishing doi:10.1088\\/1755-1315\\/839\\/4\\/042085 Dustov Xamro Bozorovich. Journal of Physics: Conference Series. Research the content of waste (yellow oil) of the shurtan gas chemical complex in Uzbekistan. 1889 (2021) 022057. IOP Publishing. DOI:10.1088\\/1742-6596\\/1889\\/2\\/022057. R.1-9\\nDustov Xamro Bozorovich AGRITECH-V-2021. IOP Conf. Series: Earth and Environmental Science Fractional composition of the waste yellow oil. 839 (2021) 042080. IOP Publishing. DOI:10.1088\\/1755-1315\\/839\\/4\\/042080. Toshev Sherzod Orzievich Earth and Environmental Science Thermodynamic values of the adsorption of methanol and ethanol molecules in zeolite NH4ZSM-5 2021 IOP Conf. Ser.: Earth Environ. Sci. 839 042074\\nSharipov Qaxramon Qandiyorovich, Bozorov Jo\\u2018rabek To\\u2018ronovich. Earth and Environmental Science. Key factors reducing energy consumption in gas supply. 839 (2021) 042083.\"]},{\"key\":\"research\",\"title\":\"Research Work\",\"items\":[\":\\nLEADING SCIENTIFIC WORK AT THE DEPARTMENT:\\nCreate compositions to break up oil and oil emulsions and improve rheological properties;\\ncreation of polymineral compositions based on local cherries that are resistant to high temperatures and salts;\\nDevelopment of a technology for the production of odorants based on mercaptans containing natural gas.\",\"TEXTBOOKS AND MANUALS\",\"Monographs created by the department\"]}]', 'Oil and Gas Engineering (Upstream & Downstream)', 'The Department of Oil and Gas Business was organized on the basis of the Department of \"Technology of Oil and Gas Chemical Industry\" in accordance with the new structure of the Bukhara Engineering and Technological Institute, approved by the Ministry', '2026-07-26 00:16:43', '2026-07-27 06:31:47');
INSERT INTO `department_translations` (`id`, `department_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES ('18', '5', 'uz', 'Neft-gaz muhandisligi (upstream va downstream)', 'Neft-gaz muhandisligi (upstream va downstream)', 'The Department of Oil and Gas Business was organized on the basis of the Department of \"Technology of Oil and Gas Chemical Industry\" in accordance with the new structure of the Bukhara Engineering and Technological Institute, approved by the Ministry of Higher and Secondary Special Education of the Republic of Uzbekistan on July 10, 2019. The management of the department is entrusted to the candidate of chemical sciences, associate professor Q.Q.Sharipov.\nAt the department 1 doctor of sciences - professor, 1 candidate of sciences - associate professor, 4 doctors of philosophy (PhD), 2 senior teachers, 2 assistant teachers teach students.\nIn the 2021-2022 academic year, the Department of Oil and Gas Affairs organized the educational process for the following undergraduate and master\'s specialties:', '[{\"key\":\"overview\",\"title\":\"Umumiy ma\\u02bclumot\",\"items\":[\"Department of Oil and Gas Engineering           \\n\\nSharipov Qaxramon Qandiyorovich\\n Reception time: Every day 15:00-16: 00\\n Phone: +998 93 453 69 69\\n Email: kahramon.sharipov@mail.ru\"]},{\"key\":\"history\",\"title\":\"Kafedra tarixi\",\"items\":[\"The Department of Oil and Gas Business was organized on the basis of the Department of \\\"Technology of Oil and Gas Chemical Industry\\\" in accordance with the new structure of the Bukhara Engineering and Technological Institute, approved by the Ministry of Higher and Secondary Special Education of the Republic of Uzbekistan on July 10, 2019. The management of the department is entrusted to the candidate of chemical sciences, associate professor Q.Q.Sharipov.\\nAt the department 1 doctor of sciences - professor, 1 candidate of s