INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2306', '584', 'en', 'Dr. Sadoqat G. Siddikova', 'Transforming Technical Education for the Global Era', 'Dr. Sadoqat G. Siddikova holds a PhD in Pedagogical Sciences. Appointed in August 2023, she leads BSTU through its strategic digital education initiatives and structural modernization reforms. Previously, she served as the Rector of the Bukhara Engineering and Technology Institute, Deputy Head of the Bukhara Regional Employment Department, and Director of the \'Ishga Marhamat\' Monocenter. Dr. Siddikova is actively involved in public life as a deputy of the Regional Council of People\'s Deputies and Chair of the Executive Committee of the Bukhara Regional Ecological Party. She is the author of over 40 scientific articles focusing on education quality and industrial digitization.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2307', '584', 'uz', 'Dr. Sadoqat G. Siddikova', 'Global davr uchun texnik ta\'limni transformatsiya qilish', 'Dr. Sadoqat G. Siddikova holds a PhD in Pedagogical Sciences. Appointed in August 2023, she leads BSTU through its strategic digital education initiatives and structural modernization reforms. Previously, she served as the Rector of the Bukhara Engineering and Technology Institute, Deputy Head of the Bukhara Regional Employment Department, and Director of the \'Ishga Marhamat\' Monocenter. Dr. Siddikova is actively involved in public life as a deputy of the Regional Council of People\'s Deputies and Chair of the Executive Committee of the Bukhara Regional Ecological Party. She is the author of over 40 scientific articles focusing on education quality and industrial digitization.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2308', '584', 'ru', 'д-р Садокат Г. Сиддикова', 'Трансформация технического образования для глобальной эпохи', 'Dr. Sadoqat G. Siddikova holds a PhD in Pedagogical Sciences. Appointed in August 2023, she leads BSTU through its strategic digital education initiatives and structural modernization reforms. Previously, she served as the Rector of the Bukhara Engineering and Technology Institute, Deputy Head of the Bukhara Regional Employment Department, and Director of the \'Ishga Marhamat\' Monocenter. Dr. Siddikova is actively involved in public life as a deputy of the Regional Council of People\'s Deputies and Chair of the Executive Committee of the Bukhara Regional Ecological Party. She is the author of over 40 scientific articles focusing on education quality and industrial digitization.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2309', '584', 'ar', 'د. صداقت غ. صديقوفا', 'تحويل التعليم التقني لمواكبة العصر العالمي الجديد', 'Dr. Sadoqat G. Siddikova holds a PhD in Pedagogical Sciences. Appointed in August 2023, she leads BSTU through its strategic digital education initiatives and structural modernization reforms. Previously, she served as the Rector of the Bukhara Engineering and Technology Institute, Deputy Head of the Bukhara Regional Employment Department, and Director of the \'Ishga Marhamat\' Monocenter. Dr. Siddikova is actively involved in public life as a deputy of the Regional Council of People\'s Deputies and Chair of the Executive Committee of the Bukhara Regional Ecological Party. She is the author of over 40 scientific articles focusing on education quality and industrial digitization.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2310', '585', 'en', 'Gafforov Alisher Xolmurodovich', 'Vice Rector for Academic Affairs', 'Dr. Alisher X. Gafforov manages the core academic structure of Bukhara State Technical University. He oversees curriculum development, academic quality control, registration systems, and student credit metrics. In compliance with international standards, he has spearheaded the transition of the university\'s academic catalog to the ECTS credit-scoring system. Under his leadership, the university academic senate reviews and optimizes curriculums to match the rapid advancements in local oil, gas, and construction industries.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2311', '585', 'uz', 'Gafforov Alisher Xolmurodovich', 'Vice Rector for Academic Affairs', 'Dr. Alisher X. Gafforov manages the core academic structure of Bukhara State Technical University. He oversees curriculum development, academic quality control, registration systems, and student credit metrics. In compliance with international standards, he has spearheaded the transition of the university\'s academic catalog to the ECTS credit-scoring system. Under his leadership, the university academic senate reviews and optimizes curriculums to match the rapid advancements in local oil, gas, and construction industries.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2312', '585', 'ru', 'Gafforov Alisher Xolmurodovich', 'Проректор по учебной работе', 'Д-р Гаффоров Алишер Холмуродович руководит ключевой академической структурой Бухарского государственного технического университета. Он курирует разработку учебных планов, контроль академического качества, регистрационные процессы и мониторинг кредитных показателей студентов. В соответствии с международными стандартами под его руководством был поэтапно переведен учебный каталог университета на систему ECTS. Также при его участии Ученый совет регулярно пересматривает и оптимизирует образовательные программы с учетом динамики региональных отраслей нефти, газа и строительства.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2313', '585', 'ar', 'Gafforov Alisher Xolmurodovich', 'نائب رئيس الجامعة للشؤون الأكاديمية', 'يدير الدكتور علي شير خ. غفوروف الهيكل الأكاديمي الأساسي لجامعة بخارى الحكومية التقنية. وهو يشرف على تطوير المناهج، وضبط الجودة الأكاديمية، وإدارة التسجيل الأكاديمي، ومتابعة مؤشرات الساعات المعتمدة للطلبة. وبما يتوافق مع المعايير الدولية، قاد تنفيذ الانتقال التدريجي لفهرس البرامج التعليمية إلى نظام ECTS. كما يعمل، عبر المجلس الأكاديمي، على مراجعة الخطط الدراسية وتحديثها باستمرار بما ينسجم مع التطورات المتسارعة في قطاعات النفط والغاز والبناء على المستوى الإقليمي.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2314', '586', 'en', 'Aslitdin Badreddinovich Nizamov', 'Vice Rector for Research and Innovation', 'Dr. Aslitdin B. Nizamov is a prominent economist and professor. He directs the university\'s scientific research activities, state innovation grants, and bilateral partnerships with production enterprises (such as Uzbekneftegaz JSC). Previously, he managed the Master\'s Department from 2018 to 2024. Under his direction, the university has expanded its doctoral (PhD/DSc) programs and created several dedicated research laboratories to analyze and optimize petrochemical synthesis.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2315', '586', 'uz', 'Aslitdin Badreddinovich Nizamov', 'Vice Rector for Research and Innovation', 'Dr. Aslitdin B. Nizamov is a prominent economist and professor. He directs the university\'s scientific research activities, state innovation grants, and bilateral partnerships with production enterprises (such as Uzbekneftegaz JSC). Previously, he managed the Master\'s Department from 2018 to 2024. Under his direction, the university has expanded its doctoral (PhD/DSc) programs and created several dedicated research laboratories to analyze and optimize petrochemical synthesis.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2316', '586', 'ru', 'Aslitdin Badreddinovich Nizamov', 'Проректор по научной работе и инновациям', 'Доктор Аслитдин Б. Низамов - известный экономист и профессор. Он руководит научно-исследовательской деятельностью университета, государственными инновационными грантами и двусторонним сотрудничеством с производственными предприятиями, включая АО «Узбекнефтегаз». В 2018-2024 годах он возглавлял магистратуру университета. Под его руководством были расширены программы докторантуры (PhD/DSc) и созданы специализированные исследовательские лаборатории для анализа и оптимизации процессов нефтехимического синтеза.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2317', '586', 'ar', 'Aslitdin Badreddinovich Nizamov', 'نائب رئيس الجامعة للشؤون العلمية والابتكارات', 'يُعد الدكتور أليستدين ب. نظاموف خبيراً اقتصادياً بارزاً وأستاذاً جامعياً. وهو يقود منظومة البحث العلمي في الجامعة، والمنح الابتكارية الحكومية، والشراكات الثنائية مع مؤسسات الإنتاج، بما فيها شركة أوزبكنفتغاز. وقد تولّى إدارة قسم الماجستير خلال الفترة 2018-2024. وتحت إشرافه توسعت برامج الدكتوراه (PhD/DSc) في الجامعة، وتم إنشاء مختبرات بحثية متخصصة لتحليل عمليات التخليق البتروكيميائي وتحسينها.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2318', '587', 'en', 'Pardayeva Marhabo Davlatovna', 'First Vice Rector for Youth Affairs and Spiritual and Educational Work', 'By the order of the Minister of Higher Education, Science, and Innovations, Marhabo Davlatovna Pardayeva was appointed as the First Vice-Rector for Youth Affairs and Spiritual-Educational Work at Bukhara State Technical University. Marhabo Pardayeva was born in 1974 in Romitan district. In 1997, she graduated from Bukhara State University with a degree in history, law, and social sciences teaching. Doctor of Philosophy (DSc), Associate Professor. Before this appointment, she served as the head of the Bukhara regional department of the Republican Center for Spirituality and Enlightenment.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2319', '587', 'uz', 'Pardayeva Marhabo Davlatovna', 'First Vice Rector for Youth Affairs and Spiritual and Educational Work', 'By the order of the Minister of Higher Education, Science, and Innovations, Marhabo Davlatovna Pardayeva was appointed as the First Vice-Rector for Youth Affairs and Spiritual-Educational Work at Bukhara State Technical University. Marhabo Pardayeva was born in 1974 in Romitan district. In 1997, she graduated from Bukhara State University with a degree in history, law, and social sciences teaching. Doctor of Philosophy (DSc), Associate Professor. Before this appointment, she served as the head of the Bukhara regional department of the Republican Center for Spirituality and Enlightenment.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2320', '587', 'ru', 'Pardayeva Marhabo Davlatovna', 'Первый проректор по работе с молодежью и духовно-просветительским делам', 'Приказом министра высшего образования, науки и инноваций Мархабо Давлатовна Пардаева назначена первым проректором Бухарского государственного технического университета по работе с молодежью и духовно-просветительской деятельности. Родилась в 1974 году в Ромитанском районе. В 1997 году окончила Бухарский государственный университет по специальности преподаватель истории, права и обществознания. Доктор социологических наук (DSc), доцент. До назначения возглавляла Бухарское областное отделение Республиканского центра духовности и просвещения.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2321', '587', 'ar', 'Pardayeva Marhabo Davlatovna', 'النائب الأول لرئيس الجامعة لشؤون الشباب والعمل الروحي والتربوي', 'بقرار من وزير التعليم العالي والعلوم والابتكارات، تم تعيين مرحبو دولتوفنا باردايفا نائباً أول لرئيس جامعة بخارى الحكومية التقنية لشؤون الشباب والعمل الروحي والتربوي. وُلدت عام 1974 في منطقة رومتان، وتخرجت عام 1997 من جامعة بخارى الحكومية بتخصص تدريس التاريخ والقانون والعلوم الاجتماعية. تحمل درجة دكتوراه العلوم (DSc) في علم الاجتماع وتشغل رتبة أستاذ مشارك. وقبل هذا التكليف، تولت رئاسة فرع ولاية بخارى للمركز الجمهوري للروحانية والتنوير.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2322', '588', 'en', 'Murodjon Ulugbekovich Djurayev', 'Vice Rector for International Cooperation', 'Dr. Murodjon U. Djurayev directs the international relations of Bukhara State Technical University. He manages bilateral academic exchange partnerships, foreign project grants, and the integration of international educational standards. Dr. Djurayev oversees the university\'s double-degree agreements with leading European and Asian universities, facilitating student and staff mobility.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2323', '588', 'uz', 'Murodjon Ulugbekovich Djurayev', 'Vice Rector for International Cooperation', 'Dr. Murodjon U. Djurayev directs the international relations of Bukhara State Technical University. He manages bilateral academic exchange partnerships, foreign project grants, and the integration of international educational standards. Dr. Djurayev oversees the university\'s double-degree agreements with leading European and Asian universities, facilitating student and staff mobility.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2324', '588', 'ru', 'Murodjon Ulugbekovich Djurayev', 'Проректор по международному сотрудничеству', 'Д-р Муроджон У. Джураев руководит международным направлением Бухарского государственного технического университета. Он координирует двусторонние академические обмены, международные грантовые проекты и внедрение международных образовательных стандартов. Также он курирует соглашения о программах двойных дипломов с ведущими университетами Европы и Азии, расширяя академическую мобильность студентов и профессорско-преподавательского состава.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2325', '588', 'ar', 'Murodjon Ulugbekovich Djurayev', 'نائب رئيس الجامعة للتعاون الدولي', 'يدير الدكتور مرادجون أو. دجوراييف ملف العلاقات الدولية في جامعة بخارى الحكومية التقنية. ويشرف على شراكات التبادل الأكاديمي الثنائية، ومشروعات المنح الدولية، ومواءمة البرامج التعليمية مع المعايير الدولية. كما يتابع اتفاقيات الدرجات المزدوجة مع جامعات رائدة في أوروبا وآسيا، بما يعزز تنقل الطلبة وأعضاء هيئة التدريس أكاديمياً.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2326', '589', 'en', 'Saidov Sobir Bahronovich', 'Vice Rector for Finance and Economy', 'Dr. Sobir B. Saidov manages the financial and economic affairs of Bukhara State Technical University. He oversees the planning and finance department, accounting, marketing services, and the allocation of budget and extra-budgetary funds. He ensures the financial stability of the institution and coordinates capital projects, campus maintenance, and energy-saving audits.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2327', '589', 'uz', 'Saidov Sobir Bahronovich', 'Vice Rector for Finance and Economy', 'Dr. Sobir B. Saidov manages the financial and economic affairs of Bukhara State Technical University. He oversees the planning and finance department, accounting, marketing services, and the allocation of budget and extra-budgetary funds. He ensures the financial stability of the institution and coordinates capital projects, campus maintenance, and energy-saving audits.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2328', '589', 'ru', 'Saidov Sobir Bahronovich', 'Проректор по финансово-экономическим вопросам', 'Д-р Собир Б. Саидов руководит финансово-экономической деятельностью Бухарского государственного технического университета. Он курирует работу планово-финансового отдела, бухгалтерии, маркетинговых служб, а также распределение бюджетных и внебюджетных средств. Под его управлением обеспечиваются финансовая устойчивость вуза, реализация капитальных проектов, поддержка кампусной инфраструктуры и проведение аудитов по энергоэффективности.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2329', '589', 'ar', 'Saidov Sobir Bahronovich', 'نائب رئيس الجامعة للشؤون المالية والاقتصادية', 'يدير الدكتور صابر ب. سعيدوف الشؤون المالية والاقتصادية لجامعة بخارى الحكومية التقنية. وهو يشرف على إدارة التخطيط والمالية، والمحاسبة، وخدمات التسويق، إضافة إلى توزيع الموارد ضمن الميزانية والموارد خارج الميزانية. ومن خلال هذا الدور يضمن الاستقرار المالي للمؤسسة، ويتابع مشروعات البنية التحتية والصيانة في الحرم الجامعي، ويقود عمليات التدقيق المرتبطة بكفاءة استخدام الطاقة.', 'Main Campus, Building 1', '2026-07-16 00:25:58', '2026-07-16 00:25:58');
INSERT INTO `staff_profile_translations` (`id`, `staff_profile_id`, `locale`, `full_name`, `position`, `bio`, `office`, `created_at`, `updated_at`) VALUES ('2330', '590', 'en', 'Dr. Khojiyev Aziz Kholmurodovich', 'Dean', 'Dean', 'Daily 14:00-16:00', '2026-08-04 19:26:09', '2026-08-04 19:30:08');
