INSERT INTO `university_center_setting_translations` (`id`, `center_setting_id`, `locale`, `sidebar_title`, `structure_label`, `about_label`, `staff_label`, `default_head_desc`, `mission_label`, `support_title`, `support_desc`, `contact_btn_label`, `function_badge_label`, `created_at`, `updated_at`) VALUES ('1', '1', 'en', 'Centres and departments', 'University Structure', 'About the Center', 'Center Structure & Staff', 'Supervises daily operations, instructional standards development, training partnerships, and compliance metrics within the center.', 'Functions & Main Activities', 'Center Support', 'Have questions about specific courses, research equipment, or facilities? Contact the director.', 'Contact University', 'Mission', '2026-07-24 10:58:33', '2026-07-24 10:58:33');
INSERT INTO `university_center_setting_translations` (`id`, `center_setting_id`, `locale`, `sidebar_title`, `structure_label`, `about_label`, `staff_label`, `default_head_desc`, `mission_label`, `support_title`, `support_desc`, `contact_btn_label`, `function_badge_label`, `created_at`, `updated_at`) VALUES ('2', '1', 'ar', 'المراكز والأقسام', 'هيكل الجامعة', 'حول المركز', 'هيكل المركز والموظفون', 'يشرف على العمليات اليومية، وتطوير المعايير التعليمية، وشراكات التدريب، ومقاييس الامتثال داخل المركز.', 'المهام والأنشطة الرئيسية', 'دعم المركز', 'لديك أسئلة حول دورات معينة، معدات البحث، أو المرافق؟ اتصل بالمدير.', 'الاتصال بالجامعة', 'الرسالة', '2026-07-24 10:58:33', '2026-07-24 10:58:33');
INSERT INTO `university_center_setting_translations` (`id`, `center_setting_id`, `locale`, `sidebar_title`, `structure_label`, `about_label`, `staff_label`, `default_head_desc`, `mission_label`, `support_title`, `support_desc`, `contact_btn_label`, `function_badge_label`, `created_at`, `updated_at`) VALUES ('3', '1', 'ru', 'Центры и отделы', 'Структура университета', 'О центре', 'Структура и сотрудники центра', 'Курирует текущую деятельность, разработку учебных стандартов, партнерство в сфере обучения и показатели соблюдения нормативов в центре.', 'Функции и основная деятельность', 'Поддержка центра', 'Вопросы по конкретным курсам, научному оборудованию или помещениям? Свяжитесь с директором.', 'Связаться с университетом', 'Миссия', '2026-07-24 10:58:33', '2026-07-24 10:58:33');
INSERT INTO `university_center_setting_translations` (`id`, `center_setting_id`, `locale`, `sidebar_title`, `structure_label`, `about_label`, `staff_label`, `default_head_desc`, `mission_label`, `support_title`, `support_desc`, `contact_btn_label`, `function_badge_label`, `created_at`, `updated_at`) VALUES ('4', '1', 'uz', 'Markazlar va bo\'limlar', 'Universitet tuzilmasi', 'Markaz haqida', 'Markaz tuzilishi va xodimlari', 'Markazning kundalik faoliyatini, ta\'lim standartlarini ishlab chiqishni, o\'quv hamkorligini va muvofiqlik ko\'rsatkichlarini nazorat qiladi.', 'Vazifalar va asosiy faoliyatlar', 'Markaz yordam xizmati', 'Maxsus kurslar, ilmiy uskunalar yoki jihozlar haqida savollaringiz bormi? Direktorga murojaat qiling.', 'Universitet bilan aloqa', 'Missiya', '2026-07-24 10:58:33', '2026-07-24 10:58:33');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('1', '1', 'en', 'Digital Educational Technologies Centre', 'Muxlis Maxmudov', 'Director of the Digital Technologies Center', NULL, 'Monday – Saturday (08:30 AM – 4:30 PM)', 'The current DET traces its origins back to the 1980s. Initially, in 1978, the \'Computing Center\' was established under the Department of \'Applied Mathematics\' at the Bukhara Food and Light Industry Technology Institute. Its material and technical base consisted of a computer classroom equipped with ES-1035, version 3, later replaced by IBM PC.AT/XT computers. Extensive work is underway at the university to automate the educational process. Wi-Fi zones have been established on campus. There are 22 computer classrooms with approximately 800 computers in total.', '[\"Department for Implementation of Digital Education Technologies\",\"Network Management Department\",\"Technical Support Department\",\"Information Security Department\",\"Extensive work is underway at the university to automate the educational process.\",\"Within DET, a group of \'Developers\' has been formed who develop and maintain programs such as the electronic journal, electronic library, distance learning system \'Moodle,\' and other applications.\",\"Wi-Fi zones have been established on campus for student internet access.\",\"Bukhara State Technical University is connected to a corporate network via optical cable in partnership with Bukhara Telecom.\",\"The center maintains contractual relationships with clients and suppliers of technical resources and equipment based on the types of services and works provided.\"]', '2026-07-24 10:30:43', '2026-07-24 10:55:03');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('2', '1', 'uz', 'Raqamli ta\'lim texnologiyalari markazi', 'Muxlis Maxmudov', 'Raqamli ta\'lim texnologiyalari markazi boshlig\'i', NULL, 'Dushanba – Shanba (08:30 – 16:30)', 'Markaz universitetning o\'quv jarayonini avtomatlashtirish, kompyuter sinflari va tarmoqlarini qo\'llab-quvvatlash bilan shug\'ullanadi. Kampusda talabalarning internetga kirishi uchun Wi-Fi zonalari tashkil etilgan. Jami 22 ta kompyuter sinfi mavjud bo\'lib, 800 ga yaqin kompyuter o\'quv jarayoniga xizmat qilmoqda.', '[\"Raqamli ta\'lim texnologiyalarini joriy etish bo\'limi;\",\"Tarmoqlarni boshqarish bo\'limi;\",\"Texnik qo\'llab-quvvatlash bo\'limi;\",\"Axborot xavfsizligi bo\'limi;\",\"Elektron jurnal, elektron kutubxona va masofaviy ta\'lim tizimi (Moodle) dasturlarini ishlab chiqish va qo\'llab-quvvatlash;\",\"Talabalar internetga kirishi uchun Wi-Fi zonalarini yaratish;\",\"Kompyuter sinflari va IT-uskunalariga texnik xizmat ko\'rsatish;\",\"Internet xizmatlari va kompyuter texnikasi yetkazib beruvchilari bilan shartnomaviy munosabatlarni yuritish.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('3', '1', 'ru', 'Центр цифровых образовательных технологий', 'Мухлис Махмудов', 'Начальник центра цифровых образовательных технологий', NULL, 'Понедельник – Суббота (08:30 – 16:30)', 'Центр занимается автоматизацией учебного процесса, поддержкой компьютерных классов и сетей университета. В кампусе созданы зоны Wi-Fi для доступа студентов к интернету. Имеется 22 компьютерных класса с примерно 800 компьютерами.', '[\"\\u041e\\u0442\\u0434\\u0435\\u043b \\u0432\\u043d\\u0435\\u0434\\u0440\\u0435\\u043d\\u0438\\u044f \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u044b\\u0445 \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0439;\",\"\\u041e\\u0442\\u0434\\u0435\\u043b \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0441\\u0435\\u0442\\u044f\\u043c\\u0438;\",\"\\u041e\\u0442\\u0434\\u0435\\u043b \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0438;\",\"\\u041e\\u0442\\u0434\\u0435\\u043b \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u043e\\u0439 \\u0431\\u0435\\u0437\\u043e\\u043f\\u0430\\u0441\\u043d\\u043e\\u0441\\u0442\\u0438;\",\"\\u0420\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 \\u0438 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 \\u0442\\u0430\\u043a\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c, \\u043a\\u0430\\u043a \\u044d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u044b\\u0439 \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b, \\u044d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0430\\u044f \\u0431\\u0438\\u0431\\u043b\\u0438\\u043e\\u0442\\u0435\\u043a\\u0430 \\u0438 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430 \\u0434\\u0438\\u0441\\u0442\\u0430\\u043d\\u0446\\u0438\\u043e\\u043d\\u043d\\u043e\\u0433\\u043e \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f (Moodle);\",\"\\u0421\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u0435 \\u0437\\u043e\\u043d Wi-Fi \\u0432 \\u043a\\u0430\\u043c\\u043f\\u0443\\u0441\\u0435 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0430 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043a \\u0438\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442\\u0443;\",\"\\u0422\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0431\\u0441\\u043b\\u0443\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043a\\u043e\\u043c\\u043f\\u044c\\u044e\\u0442\\u0435\\u0440\\u043d\\u044b\\u0445 \\u043a\\u043b\\u0430\\u0441\\u0441\\u043e\\u0432 \\u0438 \\u0418\\u0422-\\u043e\\u0431\\u043e\\u0440\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f;\",\"\\u0412\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0434\\u043e\\u0433\\u043e\\u0432\\u043e\\u0440\\u043d\\u044b\\u0445 \\u043e\\u0442\\u043d\\u043e\\u0448\\u0435\\u043d\\u0438\\u0439 \\u0441 \\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0449\\u0438\\u043a\\u0430\\u043c\\u0438 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442-\\u0443\\u0441\\u043b\\u0443\\u0433 \\u0438 \\u043a\\u043e\\u043c\\u043f\\u044c\\u044e\\u0442\\u0435\\u0440\\u043d\\u043e\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0438.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('4', '1', 'ar', 'مركز تقنيات التعليم الرقمي', 'مخلص محمودوف', 'رئيس مركز التقنيات التعليمية الرقمية', NULL, 'الاثنين – السبت (08:30 صباحاً – 04:30 مساءً)', 'يعود تاريخ المركز إلى الثمانينيات. ويشرف حالياً على إدارة الشبكات المحلية والخوادم وتطوير البرمجيات والأنظمة التعليمية مثل HEMIS و Moodle. وتعمل الجامعة بجد على أتمتة العمليات التعليمية بالكامل وتوفير شبكات الـ Wi-Fi.', '[\"\\u0642\\u0633\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u061b\",\"\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0648\\u062c\\u064a\\u0647 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0634\\u0628\\u0643\\u0627\\u062a\\u061b\",\"\\u0642\\u0633\\u0645 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0641\\u0646\\u064a \\u0644\\u0623\\u062c\\u0647\\u0632\\u0629 \\u0627\\u0644\\u0643\\u0645\\u0628\\u064a\\u0648\\u062a\\u0631\\u061b\",\"\\u0642\\u0633\\u0645 \\u0623\\u0645\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0648\\u0627\\u0644\\u0634\\u0628\\u0643\\u0627\\u062a\\u061b\",\"\\u0623\\u062a\\u0645\\u062a\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062c\\u062f\\u0627\\u0648\\u0644 \\u0648\\u0627\\u0644\\u0645\\u062c\\u0644\\u0627\\u062a \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a\\u0629 \\u0648\\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0639\\u0646 \\u0628\\u0639\\u062f (Moodle)\\u061b\",\"\\u062a\\u0648\\u0641\\u064a\\u0631 \\u0634\\u0628\\u0643\\u0627\\u062a Wi-Fi \\u0648\\u062a\\u063a\\u0637\\u064a\\u0629 \\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062d\\u0631\\u0645 \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u064a \\u0644\\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0637\\u0644\\u0627\\u0628 \\u0648\\u0627\\u0644\\u0623\\u0633\\u0627\\u062a\\u0630\\u0629\\u061b\",\"\\u0635\\u064a\\u0627\\u0646\\u0629 \\u0627\\u0644\\u0641\\u0635\\u0648\\u0644 \\u0627\\u0644\\u062d\\u0627\\u0633\\u0648\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a \\u0639\\u062f\\u062f\\u0647\\u0627 22 \\u0648\\u062a\\u0648\\u0641\\u064a\\u0631 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0641\\u0646\\u064a \\u0644\\u0644\\u0623\\u062c\\u0647\\u0632\\u0629\\u061b\",\"\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0627\\u0644\\u0639\\u0644\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u062a\\u0639\\u0627\\u0642\\u062f\\u064a\\u0629 \\u0645\\u0639 \\u0645\\u0632\\u0648\\u062f\\u064a \\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0648\\u0645\\u0648\\u0631\\u062f\\u064a \\u0627\\u0644\\u0645\\u0639\\u062f\\u0627\\u062a \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('5', '2', 'en', 'Сhancellery and archival department', 'Barnoyeva Gulshanxon Subxidinovna', 'Head of Chancellery and archival department', NULL, 'Monday – Saturday (09:00 AM – 4:00 PM)', 'The Office is an independent structural subdivision of the institute and reports directly to the Rector according to the institute’s charter. The Office operates based on the laws of the Republic of Uzbekistan, Decrees, Orders, and Resolutions of the President of the Republic of Uzbekistan, Resolutions and Orders of the Cabinet of Ministers, decisions made by the Council, and relevant regulatory and methodological documents.', '[\"Organizing work processes at the institute, ensuring discipline in document management, and maintaining confidentiality in document handling.\",\"Monitoring the deadlines and quality of documents received from higher authorities.\",\"Ensuring timely execution of documents assigned to employees.\",\"Ensuring the use, accounting, and safekeeping of stamps and seals used in document management.\",\"Monitoring the implementation of management decisions.\",\"Organizing the timely transfer of documents with expired retention periods to the archive.\",\"Studying and supervising document management within the institute.\",\"Controlling the departments and journals within the institute\\u2019s structure, ensuring timely and correct registration of incoming and outgoing documents.\",\"Receiving letters and documents and sending reply letters on time.\",\"Distributing documents to deans\\u2019 offices and departments and monitoring their execution.\",\"Taking measures to improve the qualifications of office and archive staff.\",\"The Office is responsible for ensuring the fulfillment of all tasks assigned by these regulations and other normative legal documents.\",\"The Office has its own round seal, which is kept by the Head of the Office.\",\"Perform office duties honestly, conscientiously, and observe labor discipline.\",\"Properly register documents received from the Oliy Majlis, Presidential Office, Cabinet of Ministers, and other ministries, and deliver to executors.\",\"Ensure proper official formatting of outgoing documents from the institute.\",\"Promptly deliver incoming documents to executors through the automated system (edo.ijro.uz).\",\"Keep account of institute forms and regularly report to the institute Rector on all activities related to the Office.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('6', '2', 'uz', 'Devonxona va arxiv bo\'limi', 'Barnoyeva Gulshanxon Subxidinovna', 'Devonxona va arxiv bo\'limi boshlig\'i', NULL, 'Dushanba – Shanba (09:00 – 16:00)', 'Devonxona institutning mustaqil tarkibiy bo\'linmasi bo\'lib, to\'g\'ridan-to\'g\'ri rektorga bo\'ysunadi. Bo\'lim hujjatlar aylanishini, kiruvchi va chiquvchi xatlarni hamda arxiv ishlarini muvofiqlashtiradi.', '[\"Institutda ish jarayonlarini tashkil etish, ish yuritish va hujjatlar bilan ishlashda maxfiylikni ta\'minlash;\",\"Yuqori organlardan kelgan hujjatlarning bajarilish muddati va sifatini nazorat qilish;\",\"Xodimlarga yuklatilgan hujjatlarning o\'z vaqtida bajarilishini ta\'minlash;\",\"Hujjat aylanishida muhr va shtamplardan to\'g\'ri foydalanish hamda saqlanishini nazorat qilish;\",\"Rahbariyat qarorlari ijrosini nazorat qilish;\",\"Muddati tugagan hujjatlarni arxivga topshirishni tashkil etish.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('7', '2', 'ru', 'Канцелярия и архивный отдел', 'Барноева Гульшанхон Субхидиновна', 'Начальник канцелярии и архивного отдела', NULL, 'Понедельник – Суббота (09:00 – 16:00)', 'Канцелярия является самостоятельным структурным подразделением института и подчиняется непосредственно ректору. Она координирует документооборот, входящую и исходящую корреспонденцию, а также архивные дела.', '[\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0440\\u0430\\u0431\\u043e\\u0447\\u0438\\u0445 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u043e\\u0432 \\u0432 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0435, \\u043e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0438\\u0441\\u0446\\u0438\\u043f\\u043b\\u0438\\u043d\\u044b \\u0434\\u0435\\u043b\\u043e\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0430 \\u0438 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0434\\u0435\\u043d\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438.\",\"\\u041c\\u043e\\u043d\\u0438\\u0442\\u043e\\u0440\\u0438\\u043d\\u0433 \\u0441\\u0440\\u043e\\u043a\\u043e\\u0432 \\u0438 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432, \\u043f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u043d\\u044b\\u0445 \\u043e\\u0442 \\u0432\\u044b\\u0448\\u0435\\u0441\\u0442\\u043e\\u044f\\u0449\\u0438\\u0445 \\u043e\\u0440\\u0433\\u0430\\u043d\\u043e\\u0432.\",\"\\u041e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0441\\u0432\\u043e\\u0435\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432, \\u043d\\u0430\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u043a\\u0430\\u043c.\",\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0437\\u0430 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c, \\u0443\\u0447\\u0435\\u0442\\u043e\\u043c \\u0438 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u043f\\u0435\\u0447\\u0430\\u0442\\u0435\\u0439 \\u0438 \\u0448\\u0442\\u0430\\u043c\\u043f\\u043e\\u0432 \\u0432 \\u0434\\u0435\\u043b\\u043e\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0435.\",\"\\u041c\\u043e\\u043d\\u0438\\u0442\\u043e\\u0440\\u0438\\u043d\\u0433 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0439 \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0430.\",\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0441\\u0432\\u043e\\u0435\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0435\\u0440\\u0435\\u0434\\u0430\\u0447\\u0438 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0441 \\u0438\\u0441\\u0442\\u0435\\u043a\\u0448\\u0438\\u043c \\u0441\\u0440\\u043e\\u043a\\u043e\\u043c \\u0445\\u0440\\u0430\\u043d\\u0435\\u043d\\u0438\\u044f \\u0432 \\u0430\\u0440\\u0445\\u0438\\u0432.\",\"\\u0418\\u0437\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0434\\u0435\\u043b\\u043e\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0430 \\u0432 \\u043f\\u043e\\u0434\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f\\u0445 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0430.\",\"\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0437\\u0430 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0440\\u0435\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u0446\\u0438\\u0435\\u0439 \\u0432\\u0445\\u043e\\u0434\\u044f\\u0449\\u0438\\u0445 \\u0438 \\u0438\\u0441\\u0445\\u043e\\u0434\\u044f\\u0449\\u0438\\u0445 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0432 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0430\\u0445 \\u0438 \\u0434\\u0435\\u043a\\u0430\\u043d\\u0430\\u0442\\u0430\\u0445.\",\"\\u041f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0438\\u0441\\u0435\\u043c \\u0438 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432, \\u0441\\u0432\\u043e\\u0435\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f \\u043e\\u0442\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430 \\u043e\\u0442\\u0432\\u0435\\u0442\\u043e\\u0432.\",\"\\u0420\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043f\\u043e \\u0434\\u0435\\u043a\\u0430\\u043d\\u0430\\u0442\\u0430\\u043c \\u0438 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440\\u0430\\u043c \\u0438 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0437\\u0430 \\u0438\\u0445 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435\\u043c.\",\"\\u041f\\u0440\\u0438\\u043d\\u044f\\u0442\\u0438\\u0435 \\u043c\\u0435\\u0440 \\u043f\\u043e \\u043f\\u043e\\u0432\\u044b\\u0448\\u0435\\u043d\\u0438\\u044e \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u043a\\u0430\\u043d\\u0446\\u0435\\u043b\\u044f\\u0440\\u0438\\u0438 \\u0438 \\u0430\\u0440\\u0445\\u0438\\u0432\\u0430.\",\"\\u0418\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u043a\\u0430\\u043c\\u0438 \\u043a\\u0430\\u043d\\u0446\\u0435\\u043b\\u044f\\u0440\\u0438\\u0438 \\u0441\\u0432\\u043e\\u0438\\u0445 \\u043e\\u0431\\u044f\\u0437\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 \\u0447\\u0435\\u0441\\u0442\\u043d\\u043e, \\u0434\\u043e\\u0431\\u0440\\u043e\\u0441\\u043e\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e \\u0438 \\u0441\\u043e\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0438\\u0441\\u0446\\u0438\\u043f\\u043b\\u0438\\u043d\\u044b.\",\"\\u0420\\u0435\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u0446\\u0438\\u044f \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432, \\u043f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u043d\\u044b\\u0445 \\u043e\\u0442 \\u041e\\u043b\\u0438\\u0439 \\u041c\\u0430\\u0436\\u043b\\u0438\\u0441\\u0430, \\u0410\\u0434\\u043c\\u0438\\u043d\\u0438\\u0441\\u0442\\u0440\\u0430\\u0446\\u0438\\u0438 \\u041f\\u0440\\u0435\\u0437\\u0438\\u0434\\u0435\\u043d\\u0442\\u0430, \\u041a\\u0430\\u0431\\u0438\\u043d\\u0435\\u0442\\u0430 \\u041c\\u0438\\u043d\\u0438\\u0441\\u0442\\u0440\\u043e\\u0432, \\u0438 \\u043f\\u0435\\u0440\\u0435\\u0434\\u0430\\u0447\\u0430 \\u0438\\u0445 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c.\",\"\\u041e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0445\\u043e\\u0434\\u044f\\u0449\\u0438\\u0445 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0430.\",\"\\u0421\\u0432\\u043e\\u0435\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f \\u043f\\u0435\\u0440\\u0435\\u0434\\u0430\\u0447\\u0430 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c \\u0447\\u0435\\u0440\\u0435\\u0437 \\u044d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u0443\\u044e \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0443 (edo.ijro.uz).\",\"\\u0412\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0443\\u0447\\u0435\\u0442\\u0430 \\u0431\\u043b\\u0430\\u043d\\u043a\\u043e\\u0432 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0430 \\u0438 \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u0430\\u044f \\u043e\\u0442\\u0447\\u0435\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u043f\\u0435\\u0440\\u0435\\u0434 \\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u043e\\u043c.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('8', '2', 'ar', 'قسم الديوان والأرشيف (السكرتارية)', 'بارنويفا جولشانخون سوبخيدينوفنا', 'رئيس قسم الديوان والأرشيف', NULL, 'الاثنين – السبت (09:00 صباحاً – 4:00 مساءً)', 'الديوان هو وحدة هيكلية مستقلة في المعهد ويتبع مباشرة لرئيس الجامعة وفقاً لميثاق المعهد وقوانين جمهورية أوزبكستان. يختص بتنظيم عمليات تدفق المستندات والحفاظ على سرية تداولها وأرشفتها.', '[\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0628\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0648\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0627\\u0646\\u0636\\u0628\\u0627\\u0637 \\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u064a \\u0648\\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0629.\",\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0639\\u064a\\u062f \\u0648\\u062c\\u0648\\u062f\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062c\\u0647\\u0627\\u062a \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0644\\u064a\\u0627.\",\"\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062a\\u0646\\u0641\\u064a\\u0630 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a \\u0644\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u0647\\u0627\\u0645 \\u0627\\u0644\\u0645\\u0648\\u0632\\u0639\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0648\\u0638\\u0641\\u064a\\u0646.\",\"\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0648\\u062d\\u0641\\u0638 \\u0627\\u0644\\u0623\\u062e\\u062a\\u0627\\u0645 \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u0641\\u064a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0648\\u062a\\u062f\\u0627\\u0648\\u0644\\u0647\\u0627.\",\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u062a\\u0646\\u0641\\u064a\\u0630 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645\\u0627\\u062a \\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u064a\\u0629 \\u0627\\u0644\\u0635\\u0627\\u062f\\u0631\\u0629 \\u0639\\u0646 \\u0645\\u062c\\u0644\\u0633 \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629.\",\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0646\\u0642\\u0644 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a \\u0644\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0645\\u0646\\u062a\\u0647\\u064a\\u0629 \\u0627\\u0644\\u0635\\u0644\\u0627\\u062d\\u064a\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0631\\u0634\\u064a\\u0641 \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a.\",\"\\u062f\\u0631\\u0627\\u0633\\u0629 \\u0648\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u062f\\u0627\\u062e\\u0644 \\u0623\\u0642\\u0633\\u0627\\u0645 \\u0648\\u0643\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629.\",\"\\u0627\\u0644\\u0631\\u0642\\u0627\\u0628\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d \\u0644\\u0644\\u0645\\u0631\\u0627\\u0633\\u0644\\u0627\\u062a \\u0627\\u0644\\u0648\\u0627\\u0631\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0635\\u0627\\u062f\\u0631\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0639\\u0645\\u0627\\u062f\\u0627\\u062a.\",\"\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u062e\\u0637\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0631\\u0633\\u0645\\u064a\\u0629 \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644 \\u062e\\u0637\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0631\\u062f \\u0641\\u064a \\u0627\\u0644\\u0645\\u0648\\u0627\\u0639\\u064a\\u062f \\u0627\\u0644\\u0645\\u062d\\u062f\\u062f\\u0629.\",\"\\u062a\\u0648\\u0632\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0639\\u0644\\u0649 \\u0645\\u0643\\u0627\\u062a\\u0628 \\u0627\\u0644\\u0639\\u0645\\u062f\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645 \\u0648\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u062a\\u0646\\u0641\\u064a\\u0630\\u0647\\u0627.\",\"\\u0627\\u062a\\u062e\\u0627\\u0630 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0628\\u064a\\u0631 \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0631\\u0641\\u0639 \\u0643\\u0641\\u0627\\u0621\\u0629 \\u0645\\u0648\\u0638\\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631\\u062a\\u0627\\u0631\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0623\\u0631\\u0634\\u064a\\u0641.\",\"\\u0623\\u062f\\u0627\\u0621 \\u0645\\u0648\\u0638\\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631\\u062a\\u0627\\u0631\\u064a\\u0629 \\u0644\\u0648\\u0627\\u062c\\u0628\\u0627\\u062a\\u0647\\u0645 \\u0628\\u0635\\u062f\\u0642 \\u0648\\u0623\\u0645\\u0627\\u0646\\u0629 \\u0648\\u0627\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645 \\u0628\\u0627\\u0646\\u0636\\u0628\\u0627\\u0637 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u062c\\u0627\\u0631\\u064a.\",\"\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0648\\u062a\\u0635\\u0646\\u064a\\u0641 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0644\\u0645\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062c\\u0644\\u0633 \\u0627\\u0644\\u0623\\u0639\\u0644\\u0649 \\u0648\\u0627\\u0644\\u0631\\u0626\\u0627\\u0633\\u0629 \\u0648\\u0627\\u0644\\u0648\\u0632\\u0627\\u0631\\u0627\\u062a \\u0648\\u062a\\u0633\\u0644\\u064a\\u0645\\u0647\\u0627 \\u0644\\u0644\\u0645\\u0646\\u0641\\u0630\\u064a\\u0646.\",\"\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0648\\u0627\\u0644\\u0635\\u064a\\u0627\\u063a\\u0629 \\u0627\\u0644\\u0631\\u0633\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d\\u0629 \\u0644\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0635\\u0627\\u062f\\u0631\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629.\",\"\\u0627\\u0644\\u062a\\u0633\\u0644\\u064a\\u0645 \\u0627\\u0644\\u0641\\u0648\\u0631\\u064a \\u0644\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0648\\u0627\\u0631\\u062f\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0625\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u0643 (edo.ijro.uz).\",\"\\u0627\\u0644\\u0627\\u062d\\u062a\\u0641\\u0627\\u0638 \\u0628\\u0633\\u062c\\u0644\\u0627\\u062a \\u0648\\u062a\\u0648\\u0632\\u064a\\u0639 \\u0627\\u0644\\u0646\\u0645\\u0627\\u0630\\u062c \\u0627\\u0644\\u0631\\u0633\\u0645\\u064a\\u0629 \\u0644\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u062f\\u0648\\u0631\\u064a\\u0629 \\u0644\\u0644\\u0631\\u0626\\u064a\\u0633.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('9', '3', 'en', 'Monitoring and inner Control Department', 'Jalol S. Radjabov', 'Head of Monitoring and inner Control Department', NULL, '-', 'In its activities, the department complies with the Laws of the Republic of Uzbekistan, Decrees, Resolutions, and Orders of the President of the Republic of Uzbekistan, decisions and orders of the Cabinet of Ministers of the Republic of Uzbekistan, this Regulation, institute orders and Council decisions, as well as other normative legal acts.', '[\"Directly leads the department, organizes the work of the department staff, and is fully responsible for the implementation of tasks and functions assigned to the department in accordance with this Regulation.\",\"Implements measures to improve the department\'s activities and enhance the qualifications of himself\\/herself and the staff.\",\"Monitors the timely execution of legislative documents and assignments by divisions through the \'Ijro.gov.uz\' and \'Edo.ijro.uz\' systems, reviews the effectiveness of their implementation at meetings of the Institute Rector and Council, and submits consolidated reports with relevant proposals;\",\"Proposes suggestions to the Rector aimed at increasing the efficiency of organizing the implementation of legislative documents and assignments, as well as strengthening the responsibility of officials in ensuring discipline of execution within institute divisions.\",\"Submits proposals to the institute leadership regarding disciplinary actions against responsible employees in the institute\\u2019s departments, technical schools, lyceums, faculties, and departments who violate execution discipline.\",\"Organizes systematic and targeted study of the execution discipline situation in the institute\\u2019s departments, technical schools, lyceums, faculties, and departments. Prepares documents related to department activities, ensures consideration of submitted drafts, and prepares proposals.\",\"Reviews appeals from individuals and legal entities related to department activities and fully complies with execution discipline.\",\"Develops and ensures the implementation of measures to further improve the department\'s work.\",\"Controls timely receipt, registration according to established procedures, and delivery to the institute leadership and its structural divisions of letters and documents received from the Administration of the President of the Republic of Uzbekistan, the Cabinet of Ministers, other ministries, and agencies.\",\"Organizes and coordinates the quality work activity of employees in accordance with the department\'s work plan and assigned service duties.\",\"Monitors documentation of management activities, sending letters, and preparation and formalization of internal documents.\",\"Provides appropriate practical and methodological assistance for record-keeping in the institute and its divisions, and supervises their work.\",\"Cooperates with divisions to improve established procedures in record-keeping and document management.\",\"Systematically monitors the quality and timely execution of tasks assigned to the institute by decrees, resolutions, and orders of the President of the Republic of Uzbekistan;\",\"Systematically monitors the quality and timely execution of tasks assigned to the institute by resolutions and orders of the Cabinet of Ministers of the Republic of Uzbekistan;\",\"Systematically monitors the quality and timely execution of tasks assigned to the institute based on protocols of meetings held by the President of the Republic of Uzbekistan and assignments from the Administration of the President of the Republic of Uzbekistan;\",\"Conducts systematic monitoring of the execution of tasks assigned to the institute by documents of the Ministry of Higher Education, Science and Innovations (orders, joint decisions, assignments, letters, etc.);\",\"Systematically monitors the quality and timely execution of orders of the Rector of the institute by structural divisions, technical schools, lyceums, faculties, and departments;\",\"Based on the Law of the Republic of Uzbekistan \'On Appeals of Physical and Legal Persons\' and the Cabinet of Ministers Resolution No. 341, the department continuously monitors and supervises timely and proper consideration of appeals by institute divisions;\",\"Immediately informs the Rector about any violations of deadlines and procedures for consideration of appeals by responsible executors;\",\"Provides the Rector with necessary information and data on execution of legislative documents, assignments, and appeals of physical and legal persons;\",\"Regularly analyzes the execution status of tasks assigned to the institute in laws, decrees, protocols of meetings with the President of the Republic of Uzbekistan, resolutions and orders of the Cabinet of Ministers, and ministry documents; identifies shortcomings and issues requiring urgent resolution and submits them for discussion at meetings with the Rector and the Council;\",\"Regularly analyzes the implementation of institute orders by departments, technical schools, lyceums, faculties, and departments; identifies urgent issues and submits them for discussion to the Rector and institute Council;\",\"Registers and examines incoming appeals (applications, complaints, suggestions) from physical and legal persons through the President\\u2019s Virtual Reception, Prime Minister\\u2019s Virtual Receptions, ministries, and other relevant organizations in accordance with established procedures and deadlines, and ensures delivery to the executor after content review;\",\"Controls that responsible employees send reply letters (to the author of the appeal, relevant organizations, and agencies) within the established deadlines;\",\"Develops the schedule for reception of representatives of physical and legal persons by heads of divisions and responsible employees, and organizes oral receptions at the institute based on this schedule (approved by the Rector);\",\"Conducts monthly, quarterly, and annual analyses on the status of consideration of appeals received by the institute, and reports to the Rector and Council meetings;\",\"Prepares analytical reports on timely consideration of appeals by the institute\\u2019s divisions, technical schools, lyceums, faculties, and departments, and submits quarterly reports to the Ministry;\",\"Controls documents, assignments, and execution of tasks in lyceums and technical schools within the institute\\u2019s organizational structure;\",\"Carries out systematic activities related to appeals of individuals and legal entities directly related to the department\'s activities and strengthens execution discipline.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('10', '3', 'uz', 'Monitoring va ichki nazorat bo\'limi', 'Jalol S. Radjabov', 'Monitoring va ichki nazorat bo\'limi boshlig\'i', NULL, 'Dushanba – Shanba (09:00 – 16:00)', 'O\'z faoliyatida bo\'lim O\'zbekiston Respublikasi qonunlari, Prezident farmon va qarorlari, Vazirlar Mahkamasi qarorlari hamda institut Kengashi qarorlariga amal qiladi. Bo\'lim ijro intizomini va hujjatlar bajarilishini nazorat qiladi.', '[\"Bo\'lim faoliyatini boshqaradi, xodimlar ishini tashkil etadi va Nizom talablari bajarilishi uchun to\'liq javob beradi;\",\"Ijro intizomini oshirish bo\'yicha chora-tadbirlarni amalga oshiradi;\",\"Ijro.gov.uz va Edo.ijro.uz tizimlari orqali topshiriqlar bajarilishini nazorat qiladi;\",\"Jismoniy va yuridik shaxslarning murojaatlari o\'z vaqtida ko\'rib chiqilishini nazorat qiladi.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('11', '3', 'ru', 'Отдел мониторинга и внутреннего контроля', 'Джалол С. Раджабов', 'Начальник отдела мониторинга и внутреннего контроля', NULL, '-', 'В своей деятельности отдел руководствуется законами Республики Узбекистан, указами, постановлениями и распоряжениями Президента Республики Узбекистан, решениями и распоряжениями Кабинета Министров, а также внутренними приказами и решениями Совета института.', '[\"\\u041d\\u0435\\u043f\\u043e\\u0441\\u0440\\u0435\\u0434\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438\\u0442 \\u043e\\u0442\\u0434\\u0435\\u043b\\u043e\\u043c, \\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0443\\u0435\\u0442 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0443 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u043a\\u043e\\u0432 \\u0438 \\u043d\\u0435\\u0441\\u0435\\u0442 \\u043f\\u043e\\u043b\\u043d\\u0443\\u044e \\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u0437\\u0430 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0430 \\u0432 \\u0441\\u043e\\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0438\\u0438 \\u0441 \\u041f\\u043e\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435\\u043c.\",\"\\u041f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442 \\u043c\\u0435\\u0440\\u044b \\u043f\\u043e \\u0443\\u043b\\u0443\\u0447\\u0448\\u0435\\u043d\\u0438\\u044e \\u0434\\u0435\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0430 \\u0438 \\u043f\\u043e\\u0432\\u044b\\u0448\\u0435\\u043d\\u0438\\u044e \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u043a