INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('13', '4', 'en', 'Human Resources Department', 'Jumayeva Gulnoz To‘rayevna', 'Head of the Human Resources Department', NULL, 'Monday - Saturday (every day from 09:00 to 16:00)', 'Providing university units with qualified and experienced personnel together with department heads, ensuring effective use of personnel in their positions and keeping their records, and monitoring the attendance and working hours of all university staff.', '[\"Providing university units with qualified and experienced personnel together with department heads;\",\"Regularly updating information about professors, teachers, and staff working at the university in the electronic database;\",\"Entering all personnel-related data into relevant systems;\",\"Ensuring effective use of personnel in their positions and keeping their records;\",\"Monitoring the attendance and working hours of all university staff;\",\"Analyzing personnel shortages and providing suggestions on these matters;\",\"Timely implementation of assignments received from higher authorities;\",\"Participating with other department heads in preparing documents related to personnel matters;\",\"Ensuring the safekeeping of personal collective documents of professors, staff, and students (both master\\u2019s and bachelor\\u2019s) studying at the university;\",\"Determining the timing of faculty selection and supervising the preparation of related information;\",\"Organizing the preparation of certificates and information for employees;\",\"Preparing reports related to personnel issues for the Ministry of Higher Education and other reporting organizations;\",\"Preparing draft orders for hiring, dismissal, and position changes of employees and supervising their submission to management;\",\"Controlling the safekeeping and management of diploma blanks received from the Ministry of Higher and Secondary Specialized Education;\",\"Monitoring the registration of orders prepared by faculty deans;\",\"Controlling dismissals due to violations of labor discipline in coordination with the trade union;\",\"Monitoring personal collective files and student cards in the student affairs department;\",\"Signing orders related to student affairs prepared by faculty deans in coordination;\",\"Controlling the timely submission of all reports prepared by the Personnel Department;\",\"Controlling the archiving of personal documents of dismissed employees and graduated students;\",\"Annually monitoring the receipt of personal documents of first-year (bachelor) students, master\\u2019s students, and those admitted to the second higher education from the admissions committee.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('14', '4', 'uz', 'Xodimlar bo\'limi (Kadrlar bo\'limi)', 'Jumayeva Gulnoz To‘rayevna', 'Xodimlar bo\'limi boshlig\'i', NULL, 'Dushanba – Shanba (09:00 – 16:00)', 'Xodimlar bo\'limi universitetda kadrlar siyosatini amalga oshiradi. U ishga qabul qilish, mehnat shartnomalarini tuzish, shaxsiy yig\'majildlarni yuritish va xodimlarni rag\'batlantirish ishlarini nazorat qiladi.', '[\"Kadrlar tarkibini shakllantirish va ulardan unumli foydalanish;\",\"Ishga qabul qilish, boshqa lavozimga o\'tkazish va bo\'shatishni rasmiylashtirish;\",\"Mehnat daftarchalari va xodimlarning shaxsiy hujjatlarini yuritish;\",\"Mehnat intizomini nazorat qilish va rag\'batlantirish chora-tadbirlarini tayyorlash.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('15', '4', 'ru', 'Отдел кадров', 'Джумаева Гульноз Тураевна', 'Начальник отдела кадров', NULL, 'Понедельник - Суббота (каждый день с 09:00 до 16:00)', 'Обеспечивает подразделения университета квалифицированными кадрами, ведет учет персонала и контролирует трудовую дисциплину.', '[\"\\u041e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043f\\u043e\\u0434\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0439 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u0430 \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0438 \\u043e\\u043f\\u044b\\u0442\\u043d\\u044b\\u043c\\u0438 \\u043a\\u0430\\u0434\\u0440\\u0430\\u043c\\u0438 \\u0441\\u043e\\u0432\\u043c\\u0435\\u0441\\u0442\\u043d\\u043e \\u0441 \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c\\u0438 \\u043e\\u0442\\u0434\\u0435\\u043b\\u043e\\u0432;\",\"\\u0420\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0435 \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438 \\u043e \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u043e\\u0440\\u0430\\u0445, \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u0430\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f\\u0445 \\u0438 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u043a\\u0430\\u0445 \\u0432 \\u044d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u043d\\u043d\\u043e\\u0439 \\u0431\\u0430\\u0437\\u0435 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445;\",\"\\u0412\\u0432\\u043e\\u0434 \\u0432\\u0441\\u0435\\u0445 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043f\\u043e \\u043f\\u0435\\u044