\u0430\\u0442\\u043a\\u043e\\u0432;\",\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e\\u0432\\u044b\\u0448\\u0435\\u043d\\u0438\\u044f \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 \\u043c\\u043e\\u043b\\u043e\\u0434\\u044b\\u0445 \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u0430\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u0439;\",\"\\u0424\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0431\\u0430\\u0437\\u044b \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u0430\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u0441\\u043a\\u043e\\u0433\\u043e \\u0441\\u043e\\u0441\\u0442\\u0430\\u0432\\u0430;\",\"\\u041c\\u043e\\u043d\\u0438\\u0442\\u043e\\u0440\\u0438\\u043d\\u0433 \\u043f\\u043b\\u0430\\u043d\\u043e\\u0432 \\u043f\\u043e\\u0432\\u044b\\u0448\\u0435\\u043d\\u0438\\u044f \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u0430\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u0439;\",\"\\u0423\\u0447\\u0430\\u0441\\u0442\\u0438\\u0435 \\u0432 \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0438 \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a\\u043d\\u0438\\u043a\\u043e\\u0432 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0430 \\u043d\\u0430 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0443;\",\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0438 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u043f\\u0435\\u0434\\u0430\\u0433\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0438 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a\\u0438 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432;\",\"\\u0423\\u0447\\u0430\\u0441\\u0442\\u0438\\u0435 \\u0432 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0435 \\u043f\\u0440\\u0438\\u0435\\u043c\\u043d\\u043e\\u0439 \\u043a\\u043e\\u043c\\u0438\\u0441\\u0441\\u0438\\u0438 \\u0438 \\u043f\\u043e\\u0434\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0442\\u043e\\u0433\\u043e\\u0432 \\u043f\\u0440\\u0438\\u0435\\u043c\\u0430;\",\"\\u041f\\u0440\\u0438\\u0435\\u043c \\u0433\\u043e\\u0434\\u043e\\u0432\\u044b\\u0445 \\u043e\\u0442\\u0447\\u0435\\u0442\\u043e\\u0432 \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\\u043e\\u0432 \\u0438 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440, \\u043f\\u043e\\u0434\\u0433\\u043e\\u0442\\u043e\\u0432\\u043a\\u0430 \\u043f\\u0440\\u0435\\u0434\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0439 \\u043f\\u043e \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0438\\u044e \\u043d\\u043e\\u0432\\u044b\\u0445 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43');
INSERT INTO `university_center_translations` (`id`, `university_center_id`, `locale`, `name`, `head`, `head_title`, `head_description`, `office_hours`, `about`, `functions`, `created_at`, `updated_at`) VALUES ('28', '7', 'ar', 'القسم التعليمي والمنهجي', 'عزيز خوجييف خولمرودوفيتش', 'رئيس القسم التعليمي والمنهجي', NULL, 'الخميس - السبت (09:00 - 13:00)', 'يدير العمل التعليمي بالجامعة وينظم العملية التدريسية وفق المناهج والخطط المعتمدة من وزارة التعليم العالي والعلوم والابتكارات، ويتابع تنفيذ الأعباء التدريسية للأساتذة.', '[\"\\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0644\\u062c\\u0645\\u064a\\u0639 \\u0623\\u0646\\u0634\\u0637\\u0629 \\u0648\\u0645\\u0648\\u0638\\u0641\\u064a \\u0627\\u0644\\u0642\\u0633\\u0645\\u061b\",\"\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a \\u0648\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633\\u064a\\u0629 \\u0648\\u0641\\u0642\\u0627\\u064b \\u0644\\u0644\\u0645\\u0646\\u0627\\u0647\\u062c \\u0648\\u0627\\u0644\\u062e\\u0637\\u0637 \\u0627\\u0644\\u0645\\u0642\\u0631\\u0629\\u061b\",\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0648\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u062e\\u0637\\u0637 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0627\\u0647\\u062c \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u064a\\u0629\\u061b\",\"\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0644\\u064a\\u0628 \\u0627\\u0644\\u062d\\u062f\\u064a\\u062b\\u0629 \\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0645\\u0639\\u0627\\u0631\\u0641 \\u0627\\u0644\\u0637\\u0644\\u0627\\u0628 \\u0648\\u0645\\u0647\\u0627\\u0631\\u0627\\u062a\\u0647\\u0645\\u061b\",\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u062a\\u